function mostUsedWords(words: string[], k: number): string[] {
  const count = new Map<string, number>();
  for (const w of words) count.set(w, (count.get(w) ?? 0) + 1);
  // a is "worse" than b: fewer uses, or the same uses and alphabetically later
  const worse = (a: string, b: string) => {
    const ca = count.get(a)!, cb = count.get(b)!;
    return ca !== cb ? ca < cb : a > b;
  };
  const heap: string[] = [];
  const up = (i: number) => {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!worse(heap[i], heap[p])) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const down = (i: number) => {
    for (;;) {
      let m = i;
      const l = 2 * i + 1, r = l + 1;
      if (l < heap.length && worse(heap[l], heap[m])) m = l;
      if (r < heap.length && worse(heap[r], heap[m])) m = r;
      if (m === i) return;
      [heap[i], heap[m]] = [heap[m], heap[i]];
      i = m;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop()!;
    if (heap.length) { heap[0] = last; down(0); }
    return top;
  };
  for (const w of count.keys()) {
    heap.push(w);
    up(heap.length - 1);
    if (heap.length > k) pop();
  }
  const out: string[] = [];
  while (heap.length) out.push(pop());
  return out.reverse();
}

