class Worst:
    # heap entry whose ordering puts the weakest word on top
    __slots__ = ("c", "w")

    def __init__(self, c, w):
        self.c, self.w = c, w

    def __lt__(self, other):
        return self.c < other.c if self.c != other.c else self.w > other.w


class Solution:
    def mostUsedWords(self, words: List[str], k: int) -> List[str]:
        count = Counter(words)
        heap = []
        for w, c in count.items():
            heapq.heappush(heap, Worst(c, w))
            if len(heap) > k:
                heapq.heappop(heap)
        out = []
        while heap:
            out.append(heapq.heappop(heap).w)
        return out[::-1]

